(function () {
  'use strict';
  const pWin = window.parent || window;
  const pDoc = pWin.document || document;
  const STYLE_ID = 'next-week-rain-ambience-skin';
  const CSS = "/* Rain UI: endless-rain glass skin adapted from 雨美化.json for Next week if it rains */
.rain-scope {
  --rm-deep: #2a3a58;
  --rm-mid: #3d527a;
  --rm-accent: #5878a8;
  --rm-moon: #e0ebff;
  --rm-silver: #b8c8e0;
  --rm-text: #eaf0fa;
  --rm-rain: #7b9cc8;
  --rain-blue: #2c3e50;
  --water-blue: #6495ed;
  --crimson: #8b0000;
  --ink-black: #1a1a1a;
  --paper-white: rgba(253, 252, 240, 0.88);
  font-family: "Noto Serif SC", "Source Han Serif SC", "Microsoft YaHei", serif;
  color: var(--rain-blue);
}
.rain-frame {
  position: relative;
  overflow: hidden;
  isolation: isolate;
  margin: 14px 0;
  padding: 0 0 22px;
  border: 1px solid rgba(224, 235, 255, 0.38);
  border-radius: 16px;
  background:
    linear-gradient(145deg, rgba(42, 58, 88, 0.68), rgba(61, 82, 122, 0.42)),
    radial-gradient(circle at 18% 0%, rgba(224, 235, 255, 0.20), transparent 30%),
    repeating-linear-gradient(115deg, rgba(255,255,255,0.16) 0 1px, transparent 1px 9px);
  box-shadow:
    0 0 0 1px rgba(224, 235, 255, 0.12),
    0 12px 34px rgba(0, 0, 0, 0.34),
    inset 0 0 42px rgba(224, 235, 255, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.24);
  backdrop-filter: blur(14px) saturate(135%);
  -webkit-backdrop-filter: blur(14px) saturate(135%);
}
.rain-frame::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 152px;
  background-image:
    linear-gradient(to bottom, rgba(42, 58, 88, 0.18), rgba(42, 58, 88, 0.62)),
    url("https://iili.io/B49hNBs.gif");
  background-size: cover;
  background-position: center;
  border-bottom: 1px solid rgba(224, 235, 255, 0.28);
  filter: brightness(0.88) contrast(1.05) saturate(0.86);
  opacity: 0.72;
  pointer-events: none;
  z-index: -1;
}
.rain-frame::after {
  content: "☾ ･ ⋆ ˖ ࣪ ⊹ ･ ☽";
  position: absolute;
  left: 50%;
  bottom: 12px;
  transform: translateX(-50%);
  color: rgba(224, 235, 255, 0.46);
  font-size: 10px;
  letter-spacing: 5px;
  text-shadow: 0 0 8px rgba(224, 235, 255, 0.42);
  pointer-events: none;
  animation: rain-moon-drift 8s ease-in-out infinite;
}
.rain-status-bar {
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 11px 20px;
  background: rgba(42, 58, 88, 0.38);
  border-bottom: 1px solid rgba(224, 235, 255, 0.25);
  box-shadow: inset 0 0 24px rgba(88, 120, 168, 0.14);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  font-size: 0.9em;
}
.env-info {
  color: var(--rm-text);
  text-shadow: 0 0 8px rgba(224, 235, 255, 0.55);
}
.countdown {
  color: #ffd5d5;
  font-weight: 700;
  white-space: nowrap;
  text-shadow: 0 0 10px rgba(139, 0, 0, 0.34);
}
.rain-maintext {
  position: relative;
  z-index: 1;
  margin: 26px auto 12px;
  width: min(90%, 700px);
  padding: 30px;
  background:
    linear-gradient(145deg, rgba(253, 252, 240, 0.92), rgba(234, 240, 250, 0.72));
  border: 1px solid rgba(224, 235, 255, 0.48);
  border-radius: 16px;
  box-shadow:
    0 8px 26px rgba(0, 0, 0, 0.22),
    inset 0 0 0 1px rgba(255, 255, 255, 0.48);
  line-height: 1.86;
  white-space: pre-wrap;
}
.rain-maintext::before,
.rain-maintext::after {
  position: absolute;
  color: rgba(88, 120, 168, 0.48);
  text-shadow: 0 0 8px rgba(224, 235, 255, 0.55);
  pointer-events: none;
  animation: rain-corner-glow 4.8s ease-in-out infinite alternate;
}
.rain-maintext::before {
  content: "☾ ˖°";
  top: 12px;
  left: 16px;
  font-size: 13px;
  letter-spacing: 3px;
}
.rain-maintext::after {
  content: "°˖ ⋆";
  right: 16px;
  bottom: 12px;
  font-size: 12px;
  letter-spacing: 3px;
  animation-delay: 1.2s;
}
.dialogue-reiko {
  color: var(--water-blue);
  font-weight: 500;
}
.dialogue-maki {
  color: var(--ink-black);
  font-weight: 500;
}
.highlight-red {
  color: var(--crimson);
  border-bottom: 1px dashed rgba(139, 0, 0, 0.62);
}
.rain-subtext {
  position: relative;
  z-index: 1;
  margin: 12px auto;
  width: min(80%, 620px);
  padding: 14px 18px;
  background: rgba(42, 58, 88, 0.28);
  border: 1px solid rgba(224, 235, 255, 0.24);
  border-radius: 16px;
  box-shadow: inset 0 0 22px rgba(224, 235, 255, 0.05);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  font-style: italic;
  text-align: center;
  color: rgba(234, 240, 250, 0.86);
  font-size: 0.88em;
}
.rain-actions {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  padding: 14px 20px 0;
  justify-content: center;
}
.action-btn {
  display: inline-block;
  min-width: 180px;
  padding: 8px 22px;
  border: 1px solid rgba(224, 235, 255, 0.68);
  border-radius: 16px;
  background: rgba(42, 58, 88, 0.34);
  color: white !important;
  box-shadow: inset 0 0 18px rgba(224, 235, 255, 0.06);
  text-align: center;
  cursor: pointer;
  transition: background 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease, transform 0.25s ease;
}
.action-btn:hover,
.action-btn:focus-visible {
  background: rgba(139, 0, 0, 0.76);
  border-color: rgba(255, 213, 213, 0.86);
  box-shadow: 0 0 18px rgba(139, 0, 0, 0.42), inset 0 0 18px rgba(255,255,255,0.08);
  transform: translateY(-1px);
  outline: none;
}
@keyframes rain-corner-glow {
  0% { opacity: 0.42; text-shadow: 0 0 6px rgba(224, 235, 255, 0.28); }
  50% { opacity: 0.86; text-shadow: 0 0 12px rgba(224, 235, 255, 0.68), 0 0 24px rgba(88, 120, 168, 0.34); }
  100% { opacity: 0.52; text-shadow: 0 0 8px rgba(224, 235, 255, 0.4); }
}
@keyframes rain-moon-drift {
  0%, 100% { letter-spacing: 5px; opacity: 0.45; }
  50% { letter-spacing: 8px; opacity: 0.72; }
}
@media (max-width: 640px) {
  .rain-status-bar { display: block; }
  .countdown { margin-top: 4px; white-space: normal; }
  .rain-frame::before { height: 126px; }
  .rain-maintext { width: auto; margin: 18px 12px 8px; padding: 22px; }
  .rain-subtext { width: auto; margin: 10px 18px; }
  .action-btn { min-width: min(220px, 100%); }
}
@media (prefers-reduced-motion: reduce) {
  .rain-frame::after,
  .rain-maintext::before,
  .rain-maintext::after {
    animation: none;
  }
}";

  function ensureRainSkin() {
    if (pDoc.getElementById(STYLE_ID)) return;
    const style = pDoc.createElement('style');
    style.id = STYLE_ID;
    style.textContent = CSS;
    pDoc.head.appendChild(style);
  }

  ensureRainSkin();
})();

(function () {
  'use strict';

  const pWin = window.parent || window;
  const pDoc = pWin.document || document;
  const SELF_ID = 'rain-action-button-sender-v3';

  if (pWin[SELF_ID]) return;
  pWin[SELF_ID] = true;

  function cleanText(value) {
    return String(value || '')
      .replace(/\s+/g, ' ')
      .replace(/<[^>]*>/g, '')
      .trim();
  }

  function isCustomInput(text, button) {
    return button.classList.contains('action-custom') || /write your own action/i.test(text) || /custom action/i.test(text);
  }

  function getComposer() {
    return pDoc.querySelector('#send_textarea, textarea#send_textarea, textarea[name="send_textarea"], textarea');
  }

  function getSendButton() {
    return pDoc.querySelector('#send_but, #send_button, button#send_but, button[title*="Send" i], button[aria-label*="Send" i]');
  }

  function setComposerValue(text, append) {
    const textarea = getComposer();
    if (!textarea) return false;

    const current = textarea.value || '';
    const next = append && current ? current + '\n' + text : text;
    const proto = Object.getPrototypeOf(textarea);
    const descriptor = Object.getOwnPropertyDescriptor(proto, 'value') || Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value');

    if (descriptor && descriptor.set) descriptor.set.call(textarea, next);
    else textarea.value = next;

    textarea.focus();
    try {
      textarea.dispatchEvent(new pWin.InputEvent('input', { bubbles: true, inputType: 'insertText', data: text }));
    } catch (_) {
      textarea.dispatchEvent(new pWin.Event('input', { bubbles: true }));
    }
    textarea.dispatchEvent(new pWin.Event('change', { bubbles: true }));

    try {
      if (pWin.$) pWin.$(textarea).val(next).trigger('input').trigger('change');
    } catch (_) {}

    return true;
  }

  function focusComposer() {
    const textarea = getComposer();
    if (!textarea) return false;
    textarea.focus();
    return true;
  }

  async function tryContextSend(text) {
    const context = pWin.SillyTavern?.getContext?.() || pWin.getContext?.();
    const candidates = [
      context?.sendMessageAsUser,
      context?.sendMessage,
      pWin.sendMessageAsUser,
      pWin.sendMessage,
    ].filter(fn => typeof fn === 'function');

    for (const fn of candidates) {
      try {
        const result = fn.call(context || pWin, text);
        if (result && typeof result.then === 'function') await result;
        return true;
      } catch (_) {}
    }
    return false;
  }

  function trySlashSend(text) {
    const commands = [
      '/send ' + text,
      '/send ' + text + '|/trigger',
    ];
    const fns = [pWin.triggerSlash, window.triggerSlash].filter(fn => typeof fn === 'function');

    for (const fn of fns) {
      for (const command of commands) {
        try {
          fn(command);
          return true;
        } catch (_) {}
      }
    }
    return false;
  }

  function tryDomSend(text) {
    if (!setComposerValue(text, false)) return false;
    const sendButton = getSendButton();
    if (sendButton) {
      sendButton.click();
      return true;
    }

    const textarea = getComposer();
    if (textarea) {
      try {
        textarea.dispatchEvent(new pWin.KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', bubbles: true, ctrlKey: false, shiftKey: false }));
        return true;
      } catch (_) {}
    }
    return false;
  }

  async function sendAction(text) {
    if (!text || text === '...' || text === '\u2026') return;
    if (await tryContextSend(text)) return;
    if (tryDomSend(text)) return;
    trySlashSend(text);
  }

  function bindButtons(root) {
    const scope = root && root.querySelectorAll ? root : pDoc;
    scope.querySelectorAll('.action-btn').forEach(button => {
      button.setAttribute('role', 'button');
      button.setAttribute('tabindex', '0');
      button.style.pointerEvents = 'auto';
      if (!button.dataset.rainAction) button.dataset.rainAction = cleanText(button.textContent || button.innerText);
    });
  }

  function handleAction(event) {
    const button = event.target && event.target.closest && event.target.closest('.action-btn');
    if (!button) return;

    const text = cleanText(button.dataset.rainAction || button.textContent || button.innerText);
    if (!text) return;

    event.preventDefault();
    event.stopPropagation();

    if (isCustomInput(text, button)) {
      focusComposer();
      return;
    }

    sendAction(text);
  }

  bindButtons(pDoc);
  pDoc.addEventListener('click', handleAction, true);
  pDoc.addEventListener('keydown', function (event) {
    if (event.key !== 'Enter' && event.key !== ' ') return;
    const button = event.target && event.target.closest && event.target.closest('.action-btn');
    if (!button) return;
    handleAction(event);
  }, true);

  try {
    const observer = new MutationObserver(mutations => {
      for (const mutation of mutations) {
        mutation.addedNodes && mutation.addedNodes.forEach(node => {
          if (node.nodeType === 1) bindButtons(node);
        });
      }
    });
    observer.observe(pDoc.body || pDoc.documentElement, { childList: true, subtree: true });
  } catch (_) {}
})();
